import './App.css';
import React from 'react';
import Navbar from "./components/Navbar";
import AppTour from './components/AppTour';
import UpdateBanner from './components/UpdateBanner';
import SectionTabs from './components/SectionTabs';
import FishYear from "./FishYear";
import Tournaments from './Tournaments';
import TournamentDetail from './TournamentDetail';
import Home from './Home';
import AuthPage from './AuthPage';
import Profile from './Profile';
import Anglers from './Anglers';
import Admin from './Admin';
import WaitingRoom from './components/WaitingRoom';
import Waypoints from './Waypoints';
import WaypointDetail from './WaypointDetail';
import Trips from './Trips';
import TripDetail from './TripDetail';
import { AuthProvider, useAuth } from './context/AuthContext';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { rememberReturnTo, takeReturnTo } from './utils/returnTo';

// Cast & Catch is its own chunk: the game (its stage, its art inlined as data URIs, its rules) is
// about a third of what the site would otherwise send to every page. A chunk that fails to load
// (an old tab after a deploy has replaced the files) reloads the page once to pick up the new ones.
const GAME_RETRY_KEY = 'game-chunk-retry';
const FishingGame = React.lazy(() => import('./FishingGame').then((module) => {
  try { sessionStorage.removeItem(GAME_RETRY_KEY); } catch { /* storage blocked: nothing to clear */ }
  return module;
}, (error) => {
  let retried = true;
  try { retried = sessionStorage.getItem(GAME_RETRY_KEY) === '1'; sessionStorage.setItem(GAME_RETRY_KEY, '1'); } catch { /* storage blocked: don't risk a reload loop */ }
  if (retried) throw error;
  window.location.reload();
  return new Promise(() => {});
}));

function ProtectedRoute({ children }) {
  const { user, loading, isMember, membershipStatus } = useAuth();
  const location = useLocation();
  // Just signed in: the account is known a moment before its membership has been asked.
  if (loading || (user && !membershipStatus)) return <div className="loading-screen">Loading your dock...</div>;
  // An account the admin hasn't approved (or has removed) gets the waiting room on every
  // route: the database would hand any page nothing to show.
  if (user) return isMember ? children : <WaitingRoom />;
  // Signed out on a link someone shared: sign in, then land on it rather than on Home.
  const from = `${location.pathname}${location.search}${location.hash}`;
  rememberReturnTo(from);
  return <Navigate to="/account" replace state={{ from }} />;
}

// The front door, where a sign-up's confirmation email lands: pick up the link that was
// opened before signing up, if there was one.
function RootRedirect() {
  const [to] = React.useState(() => takeReturnTo() || '/home');
  return <Navigate to={to} replace />;
}

function App() {
  return (
    <AuthProvider><Router><div className="App"><Navbar /><AppTour /><UpdateBanner /><div className="page-wrapper"><SectionTabs /><Routes>
      <Route path="/" element={<RootRedirect />} />
      <Route path="/account" element={<AuthPage />} />
      <Route path="/home" element={<ProtectedRoute><Home /></ProtectedRoute>} />
      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
      <Route path="/fluke-tournament" element={<Navigate to="/tournaments" replace />} />
      <Route path="/tournaments" element={<ProtectedRoute><Tournaments /></ProtectedRoute>} />
      <Route path="/tournaments/:tournamentId" element={<ProtectedRoute><TournamentDetail /></ProtectedRoute>} />
      <Route path="/fish-year" element={<ProtectedRoute><FishYear /></ProtectedRoute>} />
      <Route path="/anglers" element={<ProtectedRoute><Anglers /></ProtectedRoute>} />
      <Route path="/waypoints" element={<ProtectedRoute><Waypoints /></ProtectedRoute>} />
      <Route path="/waypoints/:mapId" element={<ProtectedRoute><WaypointDetail /></ProtectedRoute>} />
      <Route path="/trips" element={<ProtectedRoute><Trips /></ProtectedRoute>} />
      <Route path="/trips/:tripId" element={<ProtectedRoute><TripDetail /></ProtectedRoute>} />
      <Route path="/fishing-game" element={<ProtectedRoute><React.Suspense fallback={<div className="loading-screen">Loading your dock...</div>}><FishingGame /></React.Suspense></ProtectedRoute>} />
      <Route path="/admin" element={<ProtectedRoute><Admin /></ProtectedRoute>} />
      <Route path="/admin/bugs" element={<Navigate to="/admin" replace />} />
    </Routes></div></div></Router></AuthProvider>
  );
}

export default App;
